    @Test
    void revokeTwiceReturns409() throws Exception {
        Scenario s = newScenario(1);
        String transferKey = transferKeyOf(transfer(s, uniqueKey("CMD"), s.evidenceKeys()));
        assertThat(revokeTransfer("alice", transferKey, "alice", "bob")
